 "content": "def transform(grid):
    from collections import deque
    h,w=len(grid),len(grid[0]);seen=set();objs=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=2 or (r,c) in seen:continue
        q=deque([(r,c)]);seen.add((r,c));pts=[]
        while q:
          x,y=q.popleft();pts.append((x,y))
          for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
            if 0<=a<h and 0<=b<w and grid[a][b]==2 and (a,b) not in seen:seen.add((a,b));q.append((a,b))
        if len(pts)==4:
          r0=min(x for x,y in pts);r1=max(x for x,y in pts);c0=min(y for x,y in pts);c1=max(y for x,y in pts)
          if r1-r0==1 and c1-c0==2:
            objs.append((r0,c0))
    # Convert the number of recognized motifs into a 3x6 coded bar pattern.
    # First three positions are 3; any extra motifs place 1s in row 2.
    out=[[0]*6 for _ in range(3)]
    n=len(objs)
    for i in range(min(n,3)):out[0][2*i]=3
    if n>=4:out[2][3]=1
    if n>=6:out[2][5]=1
    return out
