 "content": "def transform(grid):
    from collections import deque
    h,w=len(grid),len(grid[0]);seen=set();up=down=0
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=2 or (r,c) in seen:continue
        q=deque([(r,c)]);seen.add((r,c));pts=[]
        while q:
          x,y=q.popleft();pts.append((x,y))
          for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
            if 0<=a<h and 0<=b<w and grid[a][b]==2 and (a,b) not in seen:
              seen.add((a,b));q.append((a,b))
        if len(pts)!=4:continue
        r0=min(x for x,y in pts);r1=max(x for x,y in pts)
        c0=min(y for x,y in pts);c1=max(y for x,y in pts)
        if r1-r0==1 and c1-c0==2:
          if grid[r0][c0+1]==2:up+=1
          else:down+=1
    out=[[0]*6 for _ in range(3)]
    # Each orientation count is represented as filled cells in a 2x3 tally.
    # Up-stem motifs use color 3 at left; down-stem motifs use color 1 at right.
    for color_count,offset in ((up,0),(down,3)):
      for i in range(min(color_count,6)):
        row=0 if i%2==0 else 2
        col=offset+(i//2)*2
        out[row][col]=3 if offset==0 else 1
    return out
