            orientations.append((r0,c0,grid[r0][c0+1]==2))
    orientations.sort()
    out=[[0]*6 for _ in range(3)]
    slots=[(0,0),(0,2),(0,3),(2,0),(2,2),(2,3)]
    for (r,c,down),(rr,cc) in zip(orientations,slots):
      out[rr][cc]=3 if down else 1
    return out
