 "content": "def transform(grid):
    from collections import deque

    h, w = len(grid), len(grid[0])
    seen = set()
    n_stem_above = 0
    n_stem_below = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for a, b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == 2 and (a, b) not in seen:
                        seen.add((a, b))
                        q.append((a, b))
            if len(cells) != 4:
                continue
            r0 = min(x for x, _ in cells)
            r1 = max(x for x, _ in cells)
            c0 = min(y for _, y in cells)
            c1 = max(y for _, y in cells)
            if r1-r0 != 1 or c1-c0 != 2:
                continue
            if all(grid[r0][y] == 2 for y in range(c0, c1+1)):
                n_stem_below += 1
            else:
                n_stem_above += 1

    out = [[0] * 6 for _ in range(3)]
    # T's with the stem above the bar are color 3; those with the stem below
    # are color 1. Each orientation fills its fixed sequence of output slots.
    slots3 = [(0,0), (0,2), (2,0), (2,2)]
    slots1 = [(0,3), (0,5), (2,3), (2,5)]
    for r, c in slots3[:n_stem_above]:
        out[r][c] = 3
    for r, c in slots1[:n_stem_below]:
        out[r][c] = 1
    return out
